 gs.sword.visible=!['roll','drink','dead','down'].includes(p.state);
 gs.wasUnarmed=['roll','drink','dead','down'].includes(p.state);
 gs.ikDelay=Math.max(0,(gs.ikDelay||0)-Math.max(0,dt));
